import java.util.*;

public class Main {
    void rotate(int[] nums, int k) {
        int n = nums.length;
        k %= n;                                                    // rotating by a full length changes nothing
        for (int step = 0; step < k; step++) {                       // repeat one single step rotation k times
            int last = nums[n - 1];
            for (int i = n - 1; i > 0; i--) {
                nums[i] = nums[i - 1];
            }
            nums[0] = last;
        }
    }

    public static void main(String[] args) {
        int[] nums = {1, 2, 3, 4, 5, 6, 7};
        Main solution = new Main();
        solution.rotate(nums, 3);
        System.out.println(Arrays.toString(nums));
    }
}

