#include <bits/stdc++.h>
using namespace std;

void reverseRange(vector<int>& nums, int left, int right) {
    while (left < right) {
        swap(nums[left], nums[right]);
        left++;
        right--;
    }
}

void rotate(vector<int>& nums, int k) {
    int n = (int)nums.size();
    k %= n;
    reverseRange(nums, 0, n - 1);                                // reverse the whole array
    reverseRange(nums, 0, k - 1);                                 // reverse the first k elements
    reverseRange(nums, k, n - 1);                                  // reverse the remaining elements
}

int main() {
    vector<int> nums = {1, 2, 3, 4, 5, 6, 7};
    rotate(nums, 3);
    for (int val : nums) cout << val << " ";
    cout << endl;
    return 0;
